; widen.asm -- chapter 9: a signed byte added to sixteen bits
; generated by gen09.py
        INCLUDE "msx.inc"
        OUTPUT "widen.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        ld hl, $1000
        ld a, 3
        call move
        ld (RESULTS+0), hl      ; the new position
        ld hl, $1000
        ld a, 3
        ld e, a
        ld d, 0                 ; the velocity taken as unsigned
        add hl, de
        ld (RESULTS+2), hl      ; and the wrong position
        ld hl, $1000
        ld a, -3
        call move
        ld (RESULTS+4), hl      ; the new position
        ld hl, $1000
        ld a, -3
        ld e, a
        ld d, 0                 ; the velocity taken as unsigned
        add hl, de
        ld (RESULTS+6), hl      ; and the wrong position
        ld hl, $10FF
        ld a, 1
        call move
        ld (RESULTS+8), hl      ; the new position
        ld hl, $10FF
        ld a, 1
        ld e, a
        ld d, 0                 ; the velocity taken as unsigned
        add hl, de
        ld (RESULTS+10), hl     ; and the wrong position
        ld hl, $1000
        ld a, -128
        call move
        ld (RESULTS+12), hl     ; the new position
        ld hl, $1000
        ld a, -128
        ld e, a
        ld d, 0                 ; the velocity taken as unsigned
        add hl, de
        ld (RESULTS+14), hl     ; and the wrong position
        ld hl, $0000
        ld a, -1
        call move
        ld (RESULTS+16), hl     ; the new position
        ld hl, $0000
        ld a, -1
        ld e, a
        ld d, 0                 ; the velocity taken as unsigned
        add hl, de
        ld (RESULTS+18), hl     ; and the wrong position
stop:   jr stop

; move: HL = HL + A, with A taken as signed (-128 to 127)
move:   ld e, a                 ; E: the velocity
        add a, a                ; its sign bit, bit 7, into the carry
        sbc a, a                ; 0 - carry: $00, or $FF if it was negative
        ld d, a                 ; DE: the velocity in sixteen bits
        add hl, de
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
